%%
%[text] ## **Objectives**
%[text] - Learn how to operate systems and equipment to obtain reliable and repeatable pressure measurements during a vented hydrogen deflagration.
%[text] - Trouble shooting systems to identifying potential improvements or flaws on procedures.
%[text] - Vented Hydrogen deflagration time-series Analysis to determine maximum peak over-pressure **∆Pmax \[kPa\]**. \
%%
%[text] ## General Plan
%[text] add brief description and pictures
%%
%[text] ## **Setup Description**
%[text] add brief description and pictures
%%
%[text] ## **Pressure Sensor Positioning**
%[text] add brief description and pictures
%%
%[text] # Data Processing Procedure (DPP) Overview
%[text] **Units SI**
%[text] **0. Setup (Matlab Startup File)**
%[text] **1. Load & Overview of Raw Data Campaign**
%[text] - Load Data and Assign Variables for each group of measurements
%[text] - Loaded Data Table
%[text] - Gas Mixing Table
%[text] - DAQs System Table
%[text] - Sensors Mapping Table
%[text]     - Group / daqSystem / daqChannel / locationLabel / isBlindSensor / Notes \
%[text] **2. Data Preprocessing**
%[text] - **Unit conversion**
%[text]     - Pressure: bar to kPa
%[text]     - Concentration: ppm to vol.%
%[text] - **Time Vectors Alignment**
%[text]     - Trigger at 4V define the zero time
%[text] - **Pressure/Trigger Initial Crop**
%[text]     - In case need for clean up raw data \
%[text] **3. Exploratory Data Analysis (EDA)**
%[text] - Preliminary Observations on Data Integrity (interference, missing data or odd recordings behaviors)
%[text] - Time Domain Analysis
%[text] - Frequency Domain Analysis (FFT for each group/run) \
%[text] **4. Signal Preprocessing (filtering/sensitivity)**
%[text] - Select Campaign/Group/Run/DAQ/Channel: choose one analysis target explicitly.
%[text] - Filter Design
%[text]     - Based on EWT or FFT (depending on Blind Sensors Data Quality)
%[text] - ∆Pmax in Function of Filter Order and Low Pass Filter Cutoff Frequency \
%[text] **5. Quantity of Interest (QoI) Extraction**
%[text] - ∆Pmax
%[text] - ∆P/∆t
%[text] - Impulse
%[text] - Summary Tables \
%[text] **6. Conclusions**
%[text] - Conclusions
%[text] - Potential Improvements Suggestions for Next Campaign \
%%
%[text] %[text:anchor:H_23C559C1] ## 0. Setup (Matlab Startup File)
%[text] %[text:anchor:H_1B29D089] This m-File code prepare the environment to provide access to auxiliary files and sub-folders.
clear ; clc; close all;
format short eng
scriptRoot = fileparts(mfilename("fullpath"));
[projectRoot,AuxFcn_GS] = AuxFcn_Matlab_Startup_File_001;
auxRoot = fullfile(projectRoot, ...
    "3-Calculations-Files", "Matlab-Files", "Auxilliary_Functions");
mainFcnRoot = fullfile(projectRoot, ...
    "3-Calculations-Files", "Matlab-Files", "Main_Functions");
addpath(genpath(auxRoot));
addpath(genpath(mainFcnRoot));
%[text] Plot Colors
set(groot, 'defaultTextInterpreter', 'latex', 'defaultAxesTickLabelInterpreter','latex', 'defaultLegendInterpreter','latex');
LUCopper = [147, 86, 14]/255;LUCopper_Light = [225, 213, 199]/255;LUBlue = [17, 55, 125]/255;LUBlue_Light = [197, 204, 221]/255;
Red_Dark = [192, 0, 0]/255;Red_Light = [235, 200, 197]/255;pink = [255, 199, 206]/255;skyblue_light=[183/255 236/255 255/255];
%%
%[text] ## **1. Load & Overview of Raw Data Campaign**
%[text] ### **1.1 Load Raw Data Campaign**
%[text] #### **Campaign: VH2D-Wk22**
%[text] One-Time-Run to Generate File Structure of the Campaign
% campaigns = MainFcn_Load_VH2D_RawCampaign_001("VH2D_Wk22", ["02","03","04"]);
%[text] Load Group Raw Data
campaignMatFile = fullfile(projectRoot, ...
    "2-Data", "ConvertedData", "VH2D-Wk22", ...
    "VH2D_Wk22_Groups_02_03_04.mat");
load(campaignMatFile)
campaign = VH2D_Wk22;
%[text] ### **1.2 Raw Data Overview**
%[text] The campaign cache contains the full raw data structure. The JSON metadata files are used only to build compact, readable overview tables for the report.
metadataRoot = fullfile(projectRoot, "2-Data", "RawData", "VH2D-Wk22", "Metadata");
metadata = AuxFcn_LoadVH2DMetadata_001(metadataRoot, Groups=["02","03","04"]);
rawDataOverviewTable = AuxFcn_BuildVH2DRawOverviewTable_001(campaign, metadata);
reportTables = AuxFcn_BuildVH2DRawReportTables_001(campaign, metadata);
%[text] #### **Raw Data Load Status**
rawLoadStatusTable = reportTables.rawLoadStatus;
rawLoadStatusDisplayTable = reportTables.rawLoadStatusDisplay;
% disp(rawLoadStatusDisplayTable);
%[text] #### Channel Audit Summary
%[text] %[text:anchor:TMP_7ebd] (loaded channels vs. sensor mapping metadata)
daqSystemsToAudit = ["DAQ_1","DAQ_2_3","DAQ_4"];

[channelAuditTable, channelAuditSummaryTable, channelAuditWarningTable] = ...
    AuxFcn_BuildVH2DChannelAuditTable_001(campaign, metadata, ...
    StreamFields=daqSystemsToAudit);
% Compact evidence overview: loaded channels plus expected metadata mapping.
% disp(channelAuditSummaryTable);

% Detailed rows only when the same loaded channel changes column across runs.
% disp(channelAuditWarningTable);
%[text] #### **Run Plan Summary**
runPlanTable = reportTables.runPlan;
% disp(runPlanTable);
%[text] #### **Gas Mixing Summary**
gasMixingTable = reportTables.gasMixing;
% disp(gasMixingTable);
%[text] #### **DAQ Systems Summary**
daqSystemsTable = reportTables.daqSystems;
% disp(daqSystemsTable);
%[text] #### **Pressure Sensor Mapping Summary**
sensorMappingTable = reportTables.sensorMap;
% disp(sensorMappingTable);
%[text] #### **Group and Run Notes Table**
groupAndRunNotesTable = reportTables.groupAndRunNotes;
% disp(groupAndRunNotesTable);
%%
%[text] ## 2. Data Preprocessing
%[text] ### **2.1 Unit Conversion**
%[text] Pressure: bar to kPa and Concentration: ppm to vol.%
converted = AuxFcn_ConvertVH2DUnits_001(campaign);

conversionOverviewTable = converted.overview;
conversionSummaryTable = unique(conversionOverviewTable(:, ...
    {'Stream','RawUnit','SourceUnit','SourceUnitEvidence', ...
    'TargetUnit','Factor','Status','Rule'}), 'rows');
% disp(conversionSummaryTable);
%[text] ### **2.2 Time Vectors Alignment**
%[text] Pressure Sensors Time aligned with Trigger at 4V define the zero time
aligned = AuxFcn_AlignVH2DTimeVectors_001(converted, ...
    TriggerThreshold_V=4, ...
    ReferenceStreams="DAQ_1", ...
    AlignStreams=["DAQ_2_3","DAQ_4"]);

alignmentOverviewTable = aligned.alignmentOverview;
alignmentSummaryTable = alignmentOverviewTable( ...
    ismember(alignmentOverviewTable.RootStream, ["DAQ_1","DAQ_2_3","DAQ_4"]), ...
    {'GroupId','RunId','Stream','TriggerColumn','TriggerChannel', ...
    'TriggerTime_source_s','AppliedShift_s','Status'});
% disp(alignmentSummaryTable);
%[text] ### 2.3 Remove DC Background Offset
offsetCorrected = AuxFcn_RemoveVH2DPressureOffset_001(aligned, ...
    BaselineWindow_s=[-0.050, -0.005]);

offsetOverviewTable = offsetCorrected.offsetOverview;
offsetSummaryTable = offsetOverviewTable(:, ...
    {'GroupId','RunId','Stream','Column','Channel','Unit', ...
    'BaselineWindowStart_s','BaselineWindowEnd_s', ...
    'BaselineMean_kPa','BaselineStd_kPa','BaselineSamples','Status'});
% disp(offsetSummaryTable);
%[text] ### 2.4 Pressure/Trigger Initial Crop
pressurePreprocessed = AuxFcn_CropVH2DPressureTriggerSignals_001( ...
    offsetCorrected, ...
    CropWindow_s=[inf, Inf], ...
    StreamFields=["DAQ_1","DAQ_2_3","DAQ_4"]);
% pressurePreprocessed = AuxFcn_CropVH2DPressureTriggerSignals_001( ...
%     offsetCorrected, ...
%     CropWindow_s=[-0.010, 0.25], ...
%     StreamFields=["DAQ_1","DAQ_2_3","DAQ_4"]);

pressureCropOverviewTable = pressurePreprocessed.cropOverview;
pressureCropSummaryTable = pressureCropOverviewTable(:, ...
    {'GroupId','RunId','Stream','CropStart_s','CropEnd_s', ...
    'SourceSamples','KeptSamples','RemovedSamples','Status'});
% disp(pressureCropSummaryTable);
%[text] 
clear converted aligned offsetCorrected
%[text] ### 2.5 Preprocessed Data
%[text] #### **Group VH2D-Wk22-02 (LU vs Kistler)**
group = pressurePreprocessed.groups.Group_02;
run_Wk22_02_01 = group.runs.VH2D_Wk22_02_01;
run_Wk22_02_02 = group.runs.VH2D_Wk22_02_02;
run_Wk22_02_03 = group.runs.VH2D_Wk22_02_03;
run_Wk22_02_04 = group.runs.VH2D_Wk22_02_04;
%[text] #### **Group VH2D-Wk22-03 (LU vs DBI)**
group = pressurePreprocessed.groups.Group_03;
run_Wk22_03_01 = group.runs.VH2D_Wk22_03_01;
run_Wk22_03_02 = group.runs.VH2D_Wk22_03_02;
run_Wk22_03_03 = group.runs.VH2D_Wk22_03_03;
run_Wk22_03_04 = group.runs.VH2D_Wk22_03_04;
run_Wk22_03_05 = group.runs.VH2D_Wk22_03_05;
%[text] #### **Group VH2D-Wk22-04 (LU vs DBI)**
group = pressurePreprocessed.groups.Group_04;
run_Wk22_04_01 = group.runs.VH2D_Wk22_04_01;
run_Wk22_04_02 = group.runs.VH2D_Wk22_04_02;
run_Wk22_04_03 = group.runs.VH2D_Wk22_04_03;
run_Wk22_04_04 = group.runs.VH2D_Wk22_04_04;
run_Wk22_04_05 = group.runs.VH2D_Wk22_04_05;
%[text] ### 2.6 Plot Preprocessed Data
%[text] #### **Group VH2D-Wk22-02 (LU vs Kistler)**
%[text] **Run Wk22-02-01**
% % --- Run Wk22-02-01: Single Figure with Dynamic Axis Limits ---
% t1 = run_Wk22_02_01.DAQ_1.t_s;
% y1_p = run_Wk22_02_01.DAQ_1.signal(:,1);
% ch1_p = run_Wk22_02_01.DAQ_1.channels(1);
% y1_tr = run_Wk22_02_01.DAQ_1.signal(:,2);
% ch1_tr = run_Wk22_02_01.DAQ_1.channels(2);
% 
% t2 = run_Wk22_02_01.DAQ_4.t_s;
% y2_p = run_Wk22_02_01.DAQ_4.signal(:,1);
% ch2_p = run_Wk22_02_01.DAQ_4.channels(1);
% y2_tr = run_Wk22_02_01.DAQ_4.signal(:,2);
% ch2_tr = run_Wk22_02_01.DAQ_4.channels(2);
% 
% figure('Units','centimeters','Position',[10 10 18 12]);
% 
% % Left axis: pressures
% ax = gca;
% yyaxis(ax, 'left');
% hP1 = plot(ax, t1, y1_p, 'Color', LUBlue, 'LineStyle', '-', 'LineWidth', 0.5); hold(ax,'on');
% hP2 = plot(ax, t2, y2_p, 'Color', LUCopper, 'LineStyle', '-', 'LineWidth', 0.5);
% ylabel(ax, "Overpressure [kPa]", 'Interpreter', 'latex');
% ax.YColor = 'k';
% 
% % Right axis: triggers
% yyaxis(ax, 'right');
% hTr1 = plot(ax, t1, y1_tr, 'Color', Red_Dark, 'LineStyle', '-', 'LineWidth', 0.5); hold(ax,'on');
% hTr2 = plot(ax, t2, y2_tr, 'Color', Red_Light, 'LineStyle', ':', 'LineWidth', 0.5);
% ylabel(ax, 'Trigger Voltage [V]', 'Interpreter', 'latex');
% ax.YColor = Red_Dark;
% 
% % Common formatting
% xlabel('Time [s]', 'Interpreter', 'latex');
% title({"{\textbf{Run Wk22-02-01 (Conc. Target $H_2$ 18 vol.$\%$)}}",'LU vs Kistler DAQs','(Flush Mounted Pressure Sensors)'}, 'Interpreter', 'latex');
% 
% legend([hP1,hP2,hTr1,hTr2], ...
%     {'Pressure (DAQ-1) '+ ch1_p,'Pressure (DAQ-4) ' + ch2_p,'Trigger (DAQ-1) ' + ch1_tr,'Trigger (DAQ-4) ' + ch2_tr}, ...
%     'Location','northeast', 'Interpreter','latex');
% 
% grid on;
% 
% % --- Dynamic axis limits (5% padding) ---
% padFrac = 0.05;
% 
% % X limits combining t1 and t2
% tAll = [t1(:); t2(:)];
% tMin = min(tAll); tMax = max(tAll);
% tRange = tMax - tMin;
% if tRange == 0
%     tPad = abs(tMin)*padFrac + 1e-3;
% else
%     tPad = padFrac * tRange;
% end
% xlim(ax, [tMin - tPad, tMax + tPad]);
% 
% % Left axis (pressures)
% pAll = [y1_p(:); y2_p(:)];
% pMin = min(pAll); pMax = max(pAll);
% pRange = pMax - pMin;
% if pRange == 0
%     pPad = abs(pMin)*padFrac + 1e-3;
% else
%     pPad = padFrac * pRange;
% end
% yyaxis(ax, 'left');
% ylim(ax, [pMin - pPad, pMax + pPad]);
% 
% % Right axis (triggers)
% trAll = [y1_tr(:); y2_tr(:)];
% trMin = min(trAll); trMax = max(trAll);
% trRange = trMax - trMin;
% if trRange == 0
%     trPad = abs(trMin)*padFrac + 1e-3;
% else
%     trPad = padFrac * trRange;
% end
% yyaxis(ax, 'right');
% ylim(ax, [trMin - trPad, trMax + trPad]);
% 
% % Force aspect ratio for plotting box (apply to main axes)
% ax = gca;
% pbaspect(ax, [16 9 1]);
%[text] 
%[text] 
% --- Run Wk22-02-01: Single Figure / 2 Tiles with Dynamic Axis Limits ---
t1 = run_Wk22_02_01.DAQ_1.t_s;
y1_p = run_Wk22_02_01.DAQ_1.signal(:,1);
ch1_p = run_Wk22_02_01.DAQ_1.channels(1);
y1_tr = run_Wk22_02_01.DAQ_1.signal(:,2);
ch1_tr = run_Wk22_02_01.DAQ_1.channels(2);

t2 = run_Wk22_02_01.DAQ_4.t_s;
y2_p = run_Wk22_02_01.DAQ_4.signal(:,1);
ch2_p = run_Wk22_02_01.DAQ_4.channels(1);
y2_tr = run_Wk22_02_01.DAQ_4.signal(:,2);
ch2_tr = run_Wk22_02_01.DAQ_4.channels(2);

% Define Window Of Interest (WoI) explicitly (seconds)
LB_WoI = 0;% in seconds
UB_WoI = 0.25;% in seconds
WoI = [LB_WoI, UB_WoI];  % in seconds

% Create 1x2 tiled figure
figure('Units','centimeters','Position',[10 10 36 12]); %[output:7b8d1f82]
tiled = tiledlayout(1,2,'TileSpacing','compact','Padding','compact'); %[output:7b8d1f82]

% Left tile: Full traces (pressures + triggers)
% axFull = nexttile;
% yyaxis(axFull,'left');
% hP1 = plot(axFull, t1, y1_p, '-', 'Color', LUBlue,   'LineWidth', 0.6); hold(axFull,'on');
% hP2 = plot(axFull, t2, y2_p, '-', 'Color', LUCopper, 'LineWidth', 0.6);
% ylabel(axFull, 'Overpressure [kPa]', 'Interpreter','latex');
% yyaxis(axFull,'right');
% hTr1 = plot(axFull, t1, y1_tr, '-', 'Color', Red_Dark, 'LineWidth', 0.6); hold(axFull,'on');
% hTr2 = plot(axFull, t2, y2_tr, ':', 'Color', Red_Light, 'LineWidth', 0.6);
% ylabel(axFull, 'Trigger Voltage [V]', 'Interpreter','latex');
% xlabel(axFull, 'Time [s]', 'Interpreter','latex');
% title(axFull, 'Full Trace', 'Interpreter','latex');
% legend(axFull, [hP1,hP2,hTr1,hTr2], ...
%     {'Pressure (DAQ-1)','Pressure (DAQ-4)','Trigger (DAQ-1)','Trigger (DAQ-4)'}, ...
%     'Location','northeast', 'Interpreter','latex');
% grid(axFull,'on');

% Left axis: pressures
axFull = nexttile; %[output:7b8d1f82]
yyaxis(axFull, 'left'); %[output:7b8d1f82]
hP1 = plot(axFull, t1, y1_p, 'Color', LUBlue, 'LineStyle', '-', 'LineWidth', 0.5);  %[output:7b8d1f82]
hold(axFull,'on'); %[output:7b8d1f82]
hP2 = plot(axFull, t2, y2_p, 'Color', LUCopper, 'LineStyle', '-', 'LineWidth', 0.5); %[output:7b8d1f82]
ylabel(axFull, "Overpressure [kPa]", 'Interpreter', 'latex'); %[output:7b8d1f82]
axFull.YColor = 'k'; %[output:7b8d1f82]

% Right axis: triggers
yyaxis(axFull, 'right'); %[output:7b8d1f82]
hTr1 = plot(axFull, t1, y1_tr, 'Color', Red_Dark, 'LineStyle', '-', 'LineWidth', 0.5);  %[output:7b8d1f82]
hold(axFull,'on'); %[output:7b8d1f82]
hTr2 = plot(axFull, t2, y2_tr, 'Color', Red_Light, 'LineStyle', ':', 'LineWidth', 0.5); %[output:7b8d1f82]
ylabel(axFull, 'Trigger Voltage [V]', 'Interpreter', 'latex'); %[output:7b8d1f82]
axFull.YColor = Red_Dark; %[output:7b8d1f82]

% Common formatting
xlabel(axFull,'Time [s]', 'Interpreter', 'latex'); %[output:7b8d1f82]
title(axFull,{"{\textbf{Run Wk22-02-01 (Conc. Target $H_2$ 18 vol.$\%$)}}",'LU vs Kistler DAQs','(Flush Mounted Pressure Sensors)'}, 'Interpreter', 'latex'); %[output:7b8d1f82]

legend(axFull,[hP1,hP2,hTr1,hTr2], ... %[output:7b8d1f82]
    {'Pressure (DAQ-1) '+ ch1_p,'Pressure (DAQ-4) ' + ch2_p,'Trigger (DAQ-1) ' + ch1_tr,'Trigger (DAQ-4) ' + ch2_tr}, ... %[output:7b8d1f82]
    'Location','northeast', 'Interpreter','latex'); %[output:7b8d1f82]

grid(axFull,'on'); %[output:7b8d1f82]
hold(axFull,'off') %[output:7b8d1f82]
pbaspect(axFull, [16 9 1]); %[output:7b8d1f82]
axFull.PlotBoxAspectRatioMode = 'manual'; %[output:7b8d1f82]
% --- Dynamic axis limits (5% padding) ---
padFrac = 0.05;

% X limits combining t1 and t2
tAll = [t1(:); t2(:)];
tMin = min(tAll); tMax = max(tAll);
tRange = tMax - tMin;
if tRange == 0
    tPad = abs(tMin)*padFrac + 1e-3;
else
    tPad = padFrac * tRange;
end
xlim(axFull, [tMin - tPad, tMax + tPad]); %[output:7b8d1f82]

% Left axis (pressures)
pAll = [y1_p(:); y2_p(:)];
pMin = min(pAll); pMax = max(pAll);
pRange = pMax - pMin;
if pRange == 0
    pPad = abs(pMin)*padFrac + 1e-3;
else
    pPad = padFrac * pRange;
end
yyaxis(axFull, 'left'); %[output:7b8d1f82]
ylim(axFull, [pMin - pPad, pMax + pPad]); %[output:7b8d1f82]

% Right axis (triggers)
trAll = [y1_tr(:); y2_tr(:)];
trMin = min(trAll); trMax = max(trAll);
trRange = trMax - trMin;
if trRange == 0
    trPad = abs(trMin)*padFrac + 1e-3;
else
    trPad = padFrac * trRange;
end
yyaxis(axFull, 'right'); %[output:7b8d1f82]
ylim(axFull, [trMin - trPad, trMax + trPad]); %[output:7b8d1f82]
box on %[output:7b8d1f82]
% Right tile: Window Of Interest (pressures only)
axWoI = nexttile; %[output:7b8d1f82]
% --- Logical indexing first (strict interval) ---
idx1 = find(t1 >= WoI(1) & t1 <= WoI(2));
idx2 = find(t2 >= WoI(1) & t2 <= WoI(2));

% --- Fallback to nearest-index if logical indexing yields empty
if isempty(idx1)
    [~, i0] = min(abs(t1 - WoI(1)));
    [~, i1] = min(abs(t1 - WoI(2)));
    idx1 = min(i0,i1):max(i0,i1);
end
if isempty(idx2)
    [~, j0] = min(abs(t2 - WoI(1)));
    [~, j1] = min(abs(t2 - WoI(2)));
    idx2 = min(j0,j1):max(j0,j1);
end

% Ensure non-empty before plotting
hold(axWoI,'on'); %[output:7b8d1f82]
if ~isempty(idx1)
    plot(axWoI, t1(idx1), y1_p(idx1), '-', 'Color', LUBlue, 'LineWidth', 0.9); %[output:7b8d1f82]
end
if ~isempty(idx2)
    plot(axWoI, t2(idx2), y2_p(idx2), '-', 'Color', LUCopper, 'LineWidth', 0.9); %[output:7b8d1f82]
end
xlabel(axWoI, 'Time [s]', 'Interpreter','latex'); %[output:7b8d1f82]
ylabel(axWoI, 'Overpressure [kPa]', 'Interpreter','latex'); %[output:7b8d1f82]
title(axWoI, sprintf('Window Of Interest: [%.3f, %.3f] s', WoI(1), WoI(2)), 'Interpreter','latex'); %[output:7b8d1f82]
xlim(axWoI, WoI);  %[output:7b8d1f82]
grid(axWoI,'on'); %[output:7b8d1f82]

hold(axWoI,'off'); %[output:7b8d1f82]
pbaspect(axFull, [16 9 1]); %[output:7b8d1f82]
axFull.PlotBoxAspectRatioMode = 'manual'; %[output:7b8d1f82]
box on %[output:7b8d1f82]
% Add a single shared title above the two tiles
sgtitle(tiled, {"{\textbf{Run Wk22-02-01 (Conc. Target $H_2$ 18 vol.$\%$)}}",'LU vs Kistler DAQs','(Flush Mounted Pressure Sensors)'}, 'Interpreter', 'latex'); %[output:7b8d1f82]
% Link x-axes so zoom/pan stays synchronized
% linkaxes([axFull, axWoI], 'x');
%[text] **Run Wk22\_02\_02**
t1 = run_Wk22_02_02.DAQ_1.t_s;
y1_p = run_Wk22_02_02.DAQ_1.signal(:,1);
y1_tr = run_Wk22_02_02.DAQ_1.signal(:,2);

t2 = run_Wk22_02_02.DAQ_4.t_s;
y2_p = run_Wk22_02_02.DAQ_4.signal(:,1);
y2_tr = run_Wk22_02_02.DAQ_4.signal(:,2);

figure('Units','centimeters','Position',[10 10 18 12]);

% Left axis: pressures
ax = gca;
yyaxis(ax, 'left');
hP1 = plot(ax, t1, y1_p, 'Color', LUBlue, 'LineStyle', '-', 'LineWidth', 0.5); hold(ax,'on');
hP2 = plot(ax, t2, y2_p, 'Color', LUCopper, 'LineStyle', '-', 'LineWidth', 0.5);
ylabel(ax, "Overpressure [kPa]", 'Interpreter', 'latex');
ax.YColor = 'k';

% Right axis: triggers
yyaxis(ax, 'right');
hTr1 = plot(ax, t1, y1_tr, 'Color', Red_Dark, 'LineStyle', '-', 'LineWidth', 0.5); hold(ax,'on');
hTr2 = plot(ax, t2, y2_tr, 'Color', Red_Light, 'LineStyle', ':', 'LineWidth', 0.5);
ylabel(ax, 'Trigger Voltage [V]', 'Interpreter', 'latex');
ax.YColor = Red_Dark;

