    idxT4 = find(runK.DAQ_4.channels == daq4TriggerName, 1);
    if isempty(idxP4) || isempty(idxT4)
        warning('Run %d DAQ-4 pressure/trigger channel not found - skipping tile.', k);
        continue;
    end
    t2 = runK.DAQ_4.t_s;
    y2_p = runK.DAQ_4.signal(:,idxP4);   % pressure DAQ-4
    y2_tr = runK.DAQ_4.signal(:,idxT4);  % trigger DAQ-4

